{"node_id": "NRS_484B_440_1_o3", "law_refs": ["NRS-484B-440-1"], "subject": {"binder": "subject", "class_elements": ["ru.aggregate=DEF-NRS-484A-320::vehicle"]}, "segmentation": [{"id": "a1", "text": "Upon any highway", "role": "condition"}, {"id": "a2", "text": "outside of a business or residence district", "role": "condition"}, {"id": "a3", "text": "no person shall stop, park or leave standing any vehicle,", "role": "sibling"}, {"id": "a4", "text": "whether attended or unattended,", "role": "condition"}, {"id": "a5", "text": "upon the paved or main-traveled part of the highway", "role": "condition"}, {"id": "a6", "text": "when it is practicable to stop, park or so leave such vehicle off such part of the highway,", "role": "sibling"}, {"id": "a7", "text": "but in every event an unobstructed width of the highway opposite a standing vehicle shall be left", "role": "sibling"}, {"id": "a8", "text": "for the free passage of other vehicles", "role": "sibling"}, {"id": "a9", "text": "and a clear view of such stopped vehicles shall be available from a distance of 200 feet in each direction upon such highway.", "role": "obligation"}, {"id": "a10", "text": "This section shall not apply to the driver of any vehicle which is disabled while on the paved or main-traveled portion of a highway in such manner and to such extent that it is impossible to avoid stopping and temporarily leaving such disabled vehicle in such position.", "role": "exception"}], "elements": [{"span": "a1", "atoms": ["rel.occupies", "st.highway"], "derived": [], "justification": "st.highway is 'the entire public way between its boundary lines' (DEF-NRS-484A-095); rel.occupies anchors the subject on it. Same mapping as the index row 'on any highway'."}, {"span": "a5", "atoms": ["rel.occupies", "st.roadway"], "derived": [], "justification": "st.roadway is 'the part of a highway improved for vehicular traffic, excluding shoulder': the paved or main-traveled part; rel.occupies anchors the subject's footprint on 